CREATE OR REPLACE TRIGGER trg_salary_cap
BEFORE UPDATE OF salary ON employees
FOR EACH ROW
BEGIN
  IF :NEW.salary > :OLD.salary * 1.5 THEN
    RAISE_APPLICATION_ERROR(-20001, 'Raise above 50% for ' || :OLD.emp_id);
  END IF;
END;
