DECLARE
  CURSOR c_low (p_store VARCHAR2, p_factor NUMBER) IS
    SELECT medicine, reorder_level * p_factor - qty AS order_qty
    FROM   pharmacy_stock
    WHERE  store_id = p_store
    AND    qty < reorder_level;
  v_factor NUMBER;
BEGIN
  FOR s IN (SELECT store_id, store_type FROM stores ORDER BY store_id) LOOP
    v_factor := CASE s.store_type WHEN 'HOSPITAL' THEN 3 ELSE 2 END;
    FOR m IN c_low(s.store_id, v_factor) LOOP
      INSERT INTO reorder_req VALUES (s.store_id, m.medicine, m.order_qty);
    END LOOP;
  END LOOP;
  COMMIT;
END;
/

DECLARE
  TYPE t_nights IS TABLE OF NUMBER INDEX BY VARCHAR2(20);
  v_tot t_nights;
  v_key VARCHAR2(20);
  v_seq PLS_INTEGER := 0;
BEGIN
  FOR b IN (SELECT hotel, nights FROM hotel_bookings ORDER BY booking_id) LOOP
    IF v_tot.EXISTS(b.hotel) THEN
      v_tot(b.hotel) := v_tot(b.hotel) + b.nights;
    ELSE
      v_tot(b.hotel) := b.nights;
    END IF;
  END LOOP;
  v_key := v_tot.FIRST;
  WHILE v_key IS NOT NULL LOOP
    v_seq := v_seq + 1;
    INSERT INTO hotel_nights VALUES (v_seq, v_key, v_tot(v_key));
    v_key := v_tot.NEXT(v_key);
  END LOOP;
  COMMIT;
END;
/

DECLARE
  v_emi emi_schedule.emi_no%TYPE;
BEGIN
  FOR l IN (SELECT loan_id FROM loans ORDER BY loan_id) LOOP
    BEGIN
      SELECT emi_no INTO v_emi
      FROM   emi_schedule
      WHERE  loan_id = l.loan_id
      AND    status = 'OVERDUE';
      INSERT INTO loan_alerts VALUES (l.loan_id, 'Overdue EMI ' || v_emi);
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        INSERT INTO loan_alerts VALUES (l.loan_id, 'No overdue EMI');
      WHEN TOO_MANY_ROWS THEN
        INSERT INTO loan_alerts VALUES (l.loan_id, 'Multiple overdue EMIs');
    END;
  END LOOP;
  COMMIT;
END;
/

