DECLARE
  PROCEDURE buy(p_player VARCHAR2, p_cost NUMBER) IS
    v_coins wallets.coins%TYPE;
  BEGIN
    SELECT coins INTO v_coins FROM wallets WHERE player_id = p_player;
    IF v_coins < p_cost THEN
      RAISE_APPLICATION_ERROR(-20001, 'Not enough coins');
    END IF;
    UPDATE wallets SET coins = coins - p_cost WHERE player_id = p_player;
  END buy;
BEGIN
  FOR p IN (SELECT player_id, item_cost FROM purchases ORDER BY purchase_id) LOOP
    BEGIN
      buy(p.player_id, p.item_cost);
      INSERT INTO purchase_log VALUES (p.player_id, 'OK');
    EXCEPTION
      WHEN OTHERS THEN
        INSERT INTO purchase_log VALUES (p.player_id, SQLCODE || ' ' || SQLERRM);
    END;
  END LOOP;
  COMMIT;
END;
/

DECLARE
  CURSOR c IS SELECT roll_no, marks FROM exam_scores ORDER BY roll_no;
  TYPE t_num IS TABLE OF NUMBER;
  l_rolls t_num;
  l_marks t_num;
BEGIN
  OPEN c;
  LOOP
    FETCH c BULK COLLECT INTO l_rolls, l_marks LIMIT 2;
    EXIT WHEN l_rolls.COUNT = 0;
    FORALL i IN 1 .. l_rolls.COUNT
      INSERT INTO results (roll_no, grade)
      VALUES (l_rolls(i), CASE WHEN l_marks(i) >= 40 THEN 'PASS' ELSE 'FAIL' END);
  END LOOP;
  CLOSE c;
  COMMIT;
END;
/

